require_once __DIR__.'/app/config.php'; init_db(); require_login();
$q=trim((string)($_GET['q']??'')); $cat=trim((string)($_GET['category']??''));
[$scopeSql,$scopeParams]=accessible_vault_sql('v'); $sql="SELECT v.*,p.icon platform_icon,COUNT(c.id) total,COALESCE(SUM(c.used=0),0) unused FROM vaults v LEFT JOIN platforms p ON p.name=v.name AND p.enabled=1 LEFT JOIN codes c ON c.vault_id=v.id WHERE 1{$scopeSql}"; $params=$scopeParams;
if($q!==''){$sql.=" AND (v.name LIKE ? OR v.account LIKE ? OR v.category LIKE ? OR v.notes LIKE ?)";$x="%$q%";$params=array_merge($params,[$x,$x,$x,$x]);}
if($cat!==''){$sql.=" AND v.category=?";$params[]=$cat;}$sql.=" GROUP BY v.id ORDER BY v.favorite DESC,v.updated_at DESC";
$stmt=db()->prepare($sql);$stmt->execute($params);$vaults=$stmt->fetchAll();$cats=categories();$pageTitle='Vaults';include __DIR__.'/app/header.php';
?>
