<section class="all-vaults-section"><div class="section-head vaults-list-head"><div><h2><?=count($vaults)?> <?=count($vaults)===1?'vault':'vaults'?></h2><p>All your saved services are shown here.</p></div></div><?php if($vaults): ?><div class="vault-grid dashboard-vault-grid"><?php foreach($vaults as $v): ?><a class="vault-card dashboard-vault-card" href="vault.php?id=<?=$v['id']?>"><div class="vault-card-top"><div class="vault-icon-large"><?=platform_image(['name'=>$v['name'],'icon'=>$v['platform_icon']],'vault-platform-icon')?></div><span class="vault-arrow">↗</span></div><div class="vault-name-row"><strong><?=e($v['name'])?></strong><?php if((int)$v['favorite']): ?><span class="favorite-mark">★</span><?php endif; ?></div><div class="vault-account"><?=e($v['account']?:'No account label')?></div><div class="vault-card-footer"><span><?=e($v['category'])?></span><span><b><?=$v['unused']?></b> unused <i>·</i> <?=$v['total']?> total</span></div></a><?php endforeach; ?></div><?php else: ?><div class="empty-vault-state card"><div class="empty-vault-icon">⌕</div><h3><?=($q||$cat)?'No matching vaults':'No vaults yet'?></h3><p><?=($q||$cat)?'Try another search or clear the current filter.':'Create your first vault to start storing recovery codes.'?></p><?php if($q||$cat): ?><a class="btn" href="vaults.php">Clear filters</a><?php else: ?><a class="btn primary" href="vault.php?new=1">Create your first vault</a><?php endif; ?></div><?php endif; ?></section>
